(7560827, 1211960, 173844, '<td valign="top">Nice concise image, with the additional bonus of the implied train also out of the frame.  The array of stripes and lines is appealing.  The viewpoint seems to be that of a small child, which adds interest.</td>', 'Nice concise image, with the additional bonus of the implied train also out of the frame.  The array of stripes and lines is appealing.  The viewpoint seems to be that of a small child, which adds interest.', '2018-02-25 17:50:23.000000', NULL, 1),
(7560828, 1212010, 173844, '<td valign="top">Graphically elegant and well-composed.  The tail end of the boogie board (?) is  a fun element.  The tree and surf are nicely out of focus.  Very effective image.</td>', 'Graphically elegant and well-composed.  The tail end of the boogie board (?) is  a fun element.  The tree and surf are nicely out of focus.  Very effective image.', '2018-02-25 18:02:20.000000', NULL, 1),
