(7560846, 1211515, 3306, '<td valign="top">Very creative! Should be top 3.</td>', 'Very creative! Should be top 3.', '2018-02-25 20:46:47.000000', NULL, 1),
(7560847, 1212010, 3306, '<td valign="top">You tell a very interesting tail!</td>', 'You tell a very interesting tail!', '2018-02-25 20:47:24.000000', NULL, 1),
(7560848, 1211991, 3306, '<td valign="top">Great capture. Perfect for this challenge.</td>', 'Great capture. Perfect for this challenge.', '2018-02-25 20:48:43.000000', NULL, 1),
(7560853, 1211940, 173844, '<td valign="top">A stylish leave-taking up a snowy slope.  A terrific handling of the white expanse that sets off the high key terrain and the black dog.  Minimalist and fun, I can easily see this commanding space on a living room wall.</td>', 'A stylish leave-taking up a snowy slope.  A terrific handling of the white expanse that sets off the high key terrain and the black dog.  Minimalist and fun, I can easily see this commanding space on a living room wall.', '2018-02-25 22:17:41.000000', NULL, 1),
