(7560869, 1211961, 50695, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1077279" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/50000-54999/50695/120/Copyrighted_Image_Reuse_Prohibited_1077279.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/50000-54999/50695/120/Copyrighted_Image_Reuse_Prohibited_1077279.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/50000-54999/50695/120/Copyrighted_Image_Reuse_Prohibited_1077279.jpg"/></a></td>', '', '2018-02-25 23:06:32.000000', NULL, 1),
